import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CpZKh-tG.js";const p=JSON.parse('{"title":"Image pipeline — tooling index","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/image-pipeline.md","filePath":"reference/tooling/image-pipeline.md"}'),r={name:"reference/tooling/image-pipeline.md"};function n(i,e,c,d,l,g){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="image-pipeline-—-tooling-index" tabindex="-1">Image pipeline — tooling index <a class="header-anchor" href="#image-pipeline-—-tooling-index" aria-label="Permalink to &quot;Image pipeline — tooling index&quot;">​</a></h1><blockquote><p><strong>This is the tooling INDEX for the image pipeline</strong> — one entry per durable tool (what / when / gotcha / state), cross-linked to the deep docs. It does <strong>not</strong> re-explain the flow. For the end-to-end map (sidecar → disk → pHash → provenance → count manifest → UI), the worked example, and the ADR cross-refs, read the deep reference first:</p><ul><li><a href="./../../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a> — <strong>deep end-to-end reference</strong> (flow, source-resolution tiers, validation gates, worked example).</li><li><a href="./../../guides/image-pipeline-v2"><code>docs/guides/image-pipeline-v2.md</code></a> — operator setup for the v2 vision-scoring layer (API key, cost ledger, sidecar manifest).</li><li><a href="./../../anatomy-art-runbook"><code>docs/anatomy-art-runbook.md</code></a> — the SEPARATE spacecraft-anatomy art pipeline.</li><li><a href="./../../../AGENTS#image-pipeline--gotchas">AGENTS.md §&quot;Image pipeline — gotchas&quot;</a> — what NOT to do (canonical gotcha prose).</li><li><a href="./../../adr/TA#pipelines">docs/adr/TA.md §pipelines</a> — Pipeline 1 (asset fetch) + Pipeline 2 (provenance manifest).</li></ul></blockquote><p><strong>STANDING</strong> = re-run as part of routine sourcing/dedup/credit work. <strong>ONE-SHOT-BUT-KEPT</strong> = ran once for a specific wave/migration; kept for the recipe, not routine re-execution. (Fully-retired one-shots live in <a href="./archive"><code>scripts/_archive/</code></a>.)</p><hr><h2 id="happy-path" tabindex="-1">Happy path <a class="header-anchor" href="#happy-path" aria-label="Permalink to &quot;Happy path&quot;">​</a></h2><p>The end-to-end sequence for adding/refreshing gallery imagery (full version with disk paths + the validate-data lockstep is in <a href="./../../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a>):</p><ol><li><strong>Fetch</strong> → <code>npm run fetch-assets</code> (stages to <code>_staging/</code> by default, RFC-029).</li><li><strong>Score</strong> → <code>npm run images:score</code> (incremental vision scoring + 1x1 crops).</li><li><strong>Review</strong> → open <strong><code>/dev/staging</code></strong> (dev-only), filter, mark Promote/Prune.</li><li><strong>Promote</strong> → &quot;Apply marked actions&quot; moves files to the shipped tree, appends to <code>image-approved.json</code>, bumps the gallery count.</li><li><strong>Credit</strong> → <code>npm run build-image-provenance</code> (add <code>--offline</code> to skip Wikimedia enrichment if it hangs).</li><li><strong>Validate</strong> → <code>npm run validate-data</code> (dupes + mime + counts + provenance completeness gates).</li></ol><p><code>npm run fetch</code> chains steps 1+5 + link provenance + validate-data in one go.</p><hr><h2 id="sourcing-fetch" tabindex="-1">Sourcing + fetch <a class="header-anchor" href="#sourcing-fetch" aria-label="Permalink to &quot;Sourcing + fetch&quot;">​</a></h2><h3 id="fetch-assets-ts-—-main-fetch-entry-standing" tabindex="-1"><code>fetch-assets.ts</code> — main fetch entry <strong>(STANDING)</strong> <a class="header-anchor" href="#fetch-assets-ts-—-main-fetch-entry-standing" aria-label="Permalink to &quot;`fetch-assets.ts` — main fetch entry **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npm run fetch-assets</code> · scope: <code>-- --missions-only=&lt;id,…&gt;</code> · <code>-- --fleet-only[=&lt;id,…&gt;]</code> · <code>-- --iss-only</code> · <code>-- --no-stage</code></li><li><strong>What</strong> Build-time asset fetcher (ADR-016). NASA Images API → Wikimedia Commons fallback (agency-first per ADR-046). Round-trips every <code>.jpg</code>/<code>.jpeg</code> write through <code>sharp().jpeg()</code> (<code>lib/image-bytes.ts</code>) so on-disk bytes are valid JPEG (GH #251). Also fetches textures, agency logos, fonts.</li><li><strong>When</strong> Any new/refreshed gallery imagery; the entry point for sourcing.</li><li><strong>Gotchas</strong> Stages by default per RFC-029 — gallery-slot downloads land in <code>static/images/_staging/</code> (gitignored, off <code>/credits</code>, pruned from prod), NOT the shipped tree. Promote at <code>/dev/staging</code>. <code>--no-stage</code> restores legacy write-straight-to-main. Textures/logos/fonts and single-file covers bypass staging (see <code>lib/staging.ts</code>).</li><li><strong>State</strong> Largest script in the tree (~148 KB) — carries all the curated query/fallback maps that <code>build-image-provenance.ts</code> re-imports as the single source of truth. Opportunity: the curated maps could split into data files.</li></ul><h3 id="agency-mission-sources-ts-—-agency-first-resolver-standing-library" tabindex="-1"><code>agency-mission-sources.ts</code> — agency-first resolver <strong>(STANDING, library)</strong> <a class="header-anchor" href="#agency-mission-sources-ts-—-agency-first-resolver-standing-library" aria-label="Permalink to &quot;`agency-mission-sources.ts` — agency-first resolver **(STANDING, library)**&quot;">​</a></h3><ul><li><strong>Command</strong> (imported by <code>fetch-assets.ts</code>; not a CLI)</li><li><strong>What</strong> <code>normalizeAgency()</code> maps <code>missions/index.json</code> agency strings → closed <code>AgencyKey</code>; <code>fetchAgencyPrimaryImageUrls()</code> resolves agency-primary URLs before Commons (ADR-046). The richer multi-primary tier chain lives in <code>lib/agency-resolver.mjs</code> (consumes <code>agency-archives.json</code> schema v2).</li><li><strong>When</strong> Whenever a fetcher needs to resolve a source agency-first.</li><li><strong>Gotchas</strong> Keep agency-name casing aligned with the catalog (<code>Roscosmos</code> vs <code>ROSCOSMOS</code>) — drift here feeds the walker-fallback mis-credit gotcha downstream.</li><li><strong>State</strong> Has a co-located <code>.test.ts</code>. Opportunity: consolidate with <code>lib/agency-resolver.mjs</code> (two resolvers, overlapping responsibility).</li></ul><h3 id="source-known-gaps-ts-—-curated-hero-gap-sourcing-one-shot-but-kept" tabindex="-1"><code>source-known-gaps.ts</code> — curated hero-gap sourcing <strong>(ONE-SHOT-BUT-KEPT)</strong> <a class="header-anchor" href="#source-known-gaps-ts-—-curated-hero-gap-sourcing-one-shot-but-kept" aria-label="Permalink to &quot;`source-known-gaps.ts` — curated hero-gap sourcing **(ONE-SHOT-BUT-KEPT)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/source-known-gaps.ts [--dry]</code></li><li><strong>What</strong> Sources the <code>KNOWN_HERO_GAPS</code> entries (#5 Phase 4) from a curated agency-first <code>SOURCING_MAP</code> (Commons title OR <code>copyFrom</code> a sibling surface). Writes <code>01.jpg</code> + <code>01.1x1.jpg</code>, removes the sourced id from the hero-coverage allowlist. Idempotent.</li><li><strong>When</strong> Re-run if new hero gaps are added to the map; otherwise the recipe.</li><li><strong>Gotchas</strong> 1x1 is the only variant generated (variant policy below).</li><li><strong>State</strong> Map is frozen at the #5 backfill set. Opportunity: fold into a generic gap filler.</li></ul><h3 id="fill-gallery-gaps-ts-—-auto-query-gap-fill-standing" tabindex="-1"><code>fill-gallery-gaps.ts</code> — auto-query gap fill <strong>(STANDING)</strong> <a class="header-anchor" href="#fill-gallery-gaps-ts-—-auto-query-gap-fill-standing" aria-label="Permalink to &quot;`fill-gallery-gaps.ts` — auto-query gap fill **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/fill-gallery-gaps.ts [--dry]</code></li><li><strong>What</strong> Walks galleries, finds entities under TARGET (5) slots, sources extras from Commons. pHash-checks each candidate against the entity&#39;s slots AND the global corpus before landing (never introduces a near-dupe).</li><li><strong>When</strong> After pruning, or any time galleries are under target.</li><li><strong>Gotchas</strong> Derives the query from the entity id (<code>luna10</code> → &quot;luna10&quot;), which misses Commons&#39; canonical naming — use <code>fill-curated-queries.ts</code> for those. Run <code>compute-phash.ts --force</code> first if slots were just renamed (stale cache lets dupes through).</li><li><strong>State</strong> STANDING. Writes <code>docs/provenance/fill-gallery-gaps-report.md</code>.</li></ul><h3 id="fill-curated-queries-ts-—-targeted-gap-fill-one-shot-but-kept" tabindex="-1"><code>fill-curated-queries.ts</code> — targeted gap fill <strong>(ONE-SHOT-BUT-KEPT)</strong> <a class="header-anchor" href="#fill-curated-queries-ts-—-targeted-gap-fill-one-shot-but-kept" aria-label="Permalink to &quot;`fill-curated-queries.ts` — targeted gap fill **(ONE-SHOT-BUT-KEPT)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/fill-curated-queries.ts [--dry]</code></li><li><strong>What</strong> Same pHash-guarded fill as above, but with hand-curated per-entity Commons queries for the entities the auto-query couldn&#39;t reach (canonical category / mission designation).</li><li><strong>When</strong> Re-run if the curated query map gains entries.</li><li><strong>Gotchas</strong> Same pHash-cache-staleness caveat.</li><li><strong>State</strong> Query map frozen at the 2026-06-14 under-target set.</li></ul><h3 id="fetch-fleet-sub-a-curation-ts-—-fleet-single-image-top-up-one-shot-but-kept" tabindex="-1"><code>fetch-fleet-sub-a-curation.ts</code> — fleet single-image top-up <strong>(ONE-SHOT-BUT-KEPT)</strong> <a class="header-anchor" href="#fetch-fleet-sub-a-curation-ts-—-fleet-single-image-top-up-one-shot-but-kept" aria-label="Permalink to &quot;`fetch-fleet-sub-a-curation.ts` — fleet single-image top-up **(ONE-SHOT-BUT-KEPT)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/fetch-fleet-sub-a-curation.ts</code></li><li><strong>What</strong> Adds 1 image each to 8 single-image non-NASA fleet entries (GH #255) via the Wikipedia REST summary API. URLs hand-validated; goes through <code>coerceToJpeg</code>.</li><li><strong>When</strong> Recipe for hard-to-source non-NASA hardware; not routine.</li><li><strong>Gotchas</strong> Run <code>npm run images:score -- --new-only</code> afterward.</li><li><strong>State</strong> Frozen curation list.</li></ul><hr><h2 id="vision-scoring-image-pipeline-v2" tabindex="-1">Vision scoring (Image Pipeline v2) <a class="header-anchor" href="#vision-scoring-image-pipeline-v2" aria-label="Permalink to &quot;Vision scoring (Image Pipeline v2)&quot;">​</a></h2><h3 id="score-images-ts-scripts-vision-—-vision-scorer-standing" tabindex="-1"><code>score-images.ts</code> + <code>scripts/vision/</code> — vision scorer <strong>(STANDING)</strong> <a class="header-anchor" href="#score-images-ts-scripts-vision-—-vision-scorer-standing" aria-label="Permalink to &quot;`score-images.ts` + `scripts/vision/` — vision scorer **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npm run images:score</code> (incremental/<code>--new-only</code> implicit) · <code>-- --all</code> · <code>-- --mission &lt;id&gt;</code> · <code>-- --agency &lt;name&gt;</code> · <code>-- --force-score</code> · <code>-- --skip-crops</code> / <code>-- --skip-scoring</code></li><li><strong>What</strong> Orchestrator (PRD-018 / RFC-022). For new/changed images: Anthropic vision score (subject, category, focal point) → 1x1 crop variants → writes <code>static/data/image-vision.json</code>. Default run is effectively free (cache hits).</li><li><strong>When</strong> After any fetch; before promote/prune ranking (prune-image-slots reads the scores).</li><li><strong>Gotchas</strong> Needs <code>ANTHROPIC_API_KEY</code> (loaded from <code>.env</code>); Claude Code subscriptions do NOT cover API calls — operator supplies the key. On 401 it logs + skips, doesn&#39;t fail the build. Cost ledger tracked via <code>src/lib/cost-ledger.ts</code> + <code>static/data/cost-ledger.json</code>.</li><li><strong>State</strong> STANDING. <code>scripts/vision/</code> modules: <ul><li><code>provider.ts</code> — <code>VisionProvider</code> interface (swap model = new impl, not a rewrite).</li><li><code>anthropic.ts</code> — default impl, Sonnet 4.6 (<code>claude-sonnet-4-6</code>); per-image ~$0.025–0.05, whole-corpus first build ≈ $67, cached runs $0.</li><li><code>prompt.ts</code> — static rubric + <code>SCORING_PROMPT_VERSION</code> (bump to invalidate the whole score cache).</li><li><code>cache.ts</code> — per-image score cache; key = source bytes + prompt version + model id ONLY (no time-based invalidation). Stored under <code>.image-cache/scores/</code> (gitignored).</li><li><code>crop-variants.ts</code> — sharp crop at the vision focal point. <strong><code>VARIANT_RATIOS</code> is the single variant lever — <code>[1x1]</code> only since 2026-06-26.</strong></li><li><code>build-manifest.ts</code> — assembles <code>image-vision.json</code> (the frontend-read sidecar; keyed to match <code>image-provenance.json</code>).</li></ul></li></ul><hr><h2 id="review-surface" tabindex="-1">Review surface <a class="header-anchor" href="#review-surface" aria-label="Permalink to &quot;Review surface&quot;">​</a></h2><h3 id="dev-staging-—-rfc-029-promote-prune-standing-dev-route" tabindex="-1"><code>/dev/staging</code> — RFC-029 promote/prune <strong>(STANDING, dev route)</strong> <a class="header-anchor" href="#dev-staging-—-rfc-029-promote-prune-standing-dev-route" aria-label="Permalink to &quot;`/dev/staging` — RFC-029 promote/prune **(STANDING, dev route)**&quot;">​</a></h3><ul><li><strong>Command</strong> open <code>http://localhost:5173/dev/staging</code> (dev-only; <code>src/routes/dev/+layout.ts</code> 404s the subtree in prod builds). Backed by <code>src/routes/dev/staging/api/</code>.</li><li><strong>What</strong> Reviews <code>static/images/_staging/</code> fetches. Filter, bulk-mark Promote/Prune, &quot;Apply marked actions&quot;: promote moves the file to the shipped tree, appends to <code>image-approved.json</code> (durable allowlist), bumps the id&#39;s contiguous gallery count.</li><li><strong>When</strong> After every staged fetch, before crediting.</li><li><strong>Gotchas</strong> Never hand-move files between <code>_staging/</code> and main + counts — moving <em>middle</em> gallery slots out leaves 404 gaps. Use the surface. <code>/credits</code> + <code>build-image-provenance.ts</code> intersect <code>image-approved.json</code> (scoped to <code>/images/</code>), so a staged/unapproved image can never be credited.</li><li><strong>State</strong> STANDING. See <a href="./../../../AGENTS#image-pipeline--gotchas">AGENTS.md §&quot;Image pipeline — gotchas&quot;</a> &quot;Staging ground&quot;.</li></ul><hr><h2 id="provenance-credits" tabindex="-1">Provenance + credits <a class="header-anchor" href="#provenance-credits" aria-label="Permalink to &quot;Provenance + credits&quot;">​</a></h2><h3 id="build-image-provenance-ts-—-the-credits-manifest-standing" tabindex="-1"><code>build-image-provenance.ts</code> — the credits manifest <strong>(STANDING)</strong> <a class="header-anchor" href="#build-image-provenance-ts-—-the-credits-manifest-standing" aria-label="Permalink to &quot;`build-image-provenance.ts` — the credits manifest **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npm run build-image-provenance</code> · <code>-- --offline</code></li><li><strong>What</strong> Walks disk image trees + curated source maps (re-imported from <code>fetch-assets.ts</code>), queries Commons <code>imageinfo</code>/<code>extmetadata</code> live, writes a TASL row per image to <code>static/data/image-provenance.json</code> + <code>docs/provenance/last-fetch-diff.md</code>. Fail-closed per ADR-047.</li><li><strong>When</strong> After every sourcing/promote pass; part of <code>npm run fetch</code>.</li><li><strong>Gotchas</strong> <code>--offline</code> skips Commons enrichment (which can hang). Never hand-write <code>author</code>/<code>license_short</code> — the Commons lookup is upstream-truth. <strong>Walker-fallback agency lookup</strong>: <code>buildWalkerFallbackEntries</code> falls through to the surface default if a non-NASA entity isn&#39;t found in the per-catalog HUMAN map → wrong credit. <strong>Concurrent-write hotspot</strong>: a parallel run can clobber fresh hotspot upserts via a load-snapshot race; re-run + verify before committing.</li><li><strong>State</strong> STANDING but huge (~105 KB) — carries the walker + all credit-derivation logic. Opportunity: extract the walker.</li></ul><h3 id="build-image-alt-baseline-ts-—-alt-text-baseline-standing" tabindex="-1"><code>build-image-alt-baseline.ts</code> — alt-text baseline <strong>(STANDING)</strong> <a class="header-anchor" href="#build-image-alt-baseline-ts-—-alt-text-baseline-standing" aria-label="Permalink to &quot;`build-image-alt-baseline.ts` — alt-text baseline **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/build-image-alt-baseline.ts [--check]</code></li><li><strong>What</strong> Builds <code>static/data/image-alt-text/en-US.json</code> from provenance captions (caption_short &gt; title &gt; description). i18n locale files overlay this (deferred to #257/v0.9).</li><li><strong>When</strong> After provenance rebuilds.</li><li><strong>Gotchas</strong> en-US only; non-English locales fall back to en-US in <code>src/lib/image-alt.ts</code>.</li><li><strong>State</strong> STANDING.</li></ul><h3 id="flag-image-ts-—-editorial-deny-list-standing" tabindex="-1"><code>flag-image.ts</code> — editorial deny-list <strong>(STANDING)</strong> <a class="header-anchor" href="#flag-image-ts-—-editorial-deny-list-standing" aria-label="Permalink to &quot;`flag-image.ts` — editorial deny-list **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/flag-image.ts &lt;path&gt; --reason &quot;&lt;why&gt;&quot;</code> · <code>--list</code> · <code>--unflag &lt;path&gt;</code></li><li><strong>What</strong> Appends to <code>static/data/image-curation.json</code> so the next scoring run skips the image and surfaces recent deny-reasons as prompt bias (RFC-022 §8).</li><li><strong>When</strong> Reviewing a bad image you want re-sourced.</li><li><strong>State</strong> STANDING.</li></ul><hr><h2 id="dedup-content-integrity" tabindex="-1">Dedup + content integrity <a class="header-anchor" href="#dedup-content-integrity" aria-label="Permalink to &quot;Dedup + content integrity&quot;">​</a></h2><h3 id="compute-phash-ts-—-phash-cache-standing" tabindex="-1"><code>compute-phash.ts</code> — pHash cache <strong>(STANDING)</strong> <a class="header-anchor" href="#compute-phash-ts-—-phash-cache-standing" aria-label="Permalink to &quot;`compute-phash.ts` — pHash cache **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/compute-phash.ts [--force]</code></li><li><strong>What</strong> DCT pHash per base <code>.jpg</code> → <code>static/data/image-phashes.json</code> (URL-path keyed). Incremental by mtime. Feeds <code>validate-image-phash-dupes.ts</code> + the source-time fill guards.</li><li><strong>When</strong> After every fetch; <strong>mandatory <code>--force</code> between any slot delete/rename and a fill run.</strong></li><li><strong>Gotchas</strong> <strong>Cache-staleness after slot rename</strong> — the cache key is the URL path, so renaming <code>03.jpg → 02.jpg</code> leaves a stale entry and fill scripts let near-dupes through. Always <code>--force</code> rebuild after renames.</li><li><strong>State</strong> STANDING. ~10–15 s on the ~2000-image corpus.</li></ul><h3 id="snapshot-phash-baseline-ts-—-baseline-allowlist-standing-intent-only" tabindex="-1"><code>snapshot-phash-baseline.ts</code> — baseline allowlist <strong>(STANDING, intent-only)</strong> <a class="header-anchor" href="#snapshot-phash-baseline-ts-—-baseline-allowlist-standing-intent-only" aria-label="Permalink to &quot;`snapshot-phash-baseline.ts` — baseline allowlist **(STANDING, intent-only)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/snapshot-phash-baseline.ts</code></li><li><strong>What</strong> Snapshots current residual near-dupes (≤ threshold) into <code>static/data/phash-baseline-allowlist.json</code> — the ratchet that lets the validator pass today while failing on NEW dupes.</li><li><strong>When</strong> Only with INTENT, after cleaning/categorising dupes — NOT routinely.</li><li><strong>Gotchas</strong> Reads <code>INLINE_ALLOWLIST</code> from <code>validate-image-phash-dupes.ts</code> (parses TS source as text) and excludes those pairs — re-snapshotting without that re-bloats the JSON. Re-snapshotting after a sourcing pass widens the gate to whatever dupes that pass added (the opposite of its purpose).</li><li><strong>State</strong> STANDING but rare. Treat like pinning a snapshot test.</li></ul><h3 id="delete-intra-entity-dupes-ts-—-dupe-delete-renumber-one-shot-but-kept" tabindex="-1"><code>delete-intra-entity-dupes.ts</code> — dupe delete + renumber <strong>(ONE-SHOT-BUT-KEPT)</strong> <a class="header-anchor" href="#delete-intra-entity-dupes-ts-—-dupe-delete-renumber-one-shot-but-kept" aria-label="Permalink to &quot;`delete-intra-entity-dupes.ts` — dupe delete + renumber **(ONE-SHOT-BUT-KEPT)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/delete-intra-entity-dupes.ts [--dry]</code></li><li><strong>What</strong> Deletes the higher-numbered slot of each hard-coded intra-entity dupe <code>PAIRS</code>, renumbers survivors contiguous. Run <code>compute-phash.ts --force</code> then <code>fill-gallery-gaps.ts</code> to top up.</li><li><strong>When</strong> Re-run if new dupe pairs are added to the list.</li><li><strong>Gotchas</strong> The <code>PAIRS</code> list is the lever; stale pHash cache between delete and fill re-introduces the same dupes.</li><li><strong>State</strong> Frozen at the post-#5 cleanup set.</li></ul><hr><h2 id="manifest-slot-maintenance" tabindex="-1">Manifest + slot maintenance <a class="header-anchor" href="#manifest-slot-maintenance" aria-label="Permalink to &quot;Manifest + slot maintenance&quot;">​</a></h2><h3 id="rebuild-gallery-manifests-ts-—-count-manifests-standing" tabindex="-1"><code>rebuild-gallery-manifests.ts</code> — count manifests <strong>(STANDING)</strong> <a class="header-anchor" href="#rebuild-gallery-manifests-ts-—-count-manifests-standing" aria-label="Permalink to &quot;`rebuild-gallery-manifests.ts` — count manifests **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/rebuild-gallery-manifests.ts [--check]</code></li><li><strong>What</strong> Walks each surface&#39;s image dir, counts non-variant base JPEGs, writes the <code>&lt;id, count&gt;</code> map (<code>mission-galleries.json</code>, <code>fleet-galleries.json</code>, <code>planet-/small-body-/satellite-/earth-object-galleries.json</code>). The source of &quot;does this entity have a gallery tab&quot;.</li><li><strong>When</strong> After any sourcing/prune/promote pass that changed disk slot counts.</li><li><strong>Gotchas</strong> <strong>Count drift = silent 404s</strong> (manifest &gt; disk) or hidden images (manifest &lt; disk). <code>validate-gallery-counts</code> gates this in preflight. Sync the manifest in the same commit as any slot delete/rename.</li><li><strong>State</strong> STANDING.</li></ul><h3 id="prune-image-slots-ts-—-top-5-cap-renumber-standing" tabindex="-1"><code>prune-image-slots.ts</code> — top-5 cap + renumber <strong>(STANDING)</strong> <a class="header-anchor" href="#prune-image-slots-ts-—-top-5-cap-renumber-standing" aria-label="Permalink to &quot;`prune-image-slots.ts` — top-5 cap + renumber **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/prune-image-slots.ts [--dry]</code></li><li><strong>What</strong> Enforces max-5 base slots per id. Ranks by <code>image-vision.json</code> score DESC, keeps top 5, renumbers 01..05 (so slot 01 = best, the default hero pick). Updates vision/provenance/sidecar manifests for renamed paths. 2-pass conflict-free rename. Idempotent.</li><li><strong>When</strong> After scoring, when an id exceeds 5 slots.</li><li><strong>Gotchas</strong> Reads vision scores — run <code>images:score</code> first or unscored slots tie last.</li><li><strong>State</strong> STANDING. Writes <code>docs/provenance/prune-image-slots-report.md</code>.</li></ul><h3 id="prune-orphan-images-ts-—-stale-file-sweep-standing" tabindex="-1"><code>prune-orphan-images.ts</code> — stale-file sweep <strong>(STANDING)</strong> <a class="header-anchor" href="#prune-orphan-images-ts-—-stale-file-sweep-standing" aria-label="Permalink to &quot;`prune-orphan-images.ts` — stale-file sweep **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/prune-orphan-images.ts [--dry]</code></li><li><strong>What</strong> Deletes dash-legacy variants, dead-code <code>*.4x3</code>/<code>*.16x9</code> variants, and dead-base variants whose base is gone. Drops the matching <code>image-vision.json</code> + alt-text keys. Idempotent.</li><li><strong>When</strong> Cleanup after the variant-policy change or stray fetcher output.</li><li><strong>Gotchas</strong> Keeps <code>.1x1</code> + base files even if the base lacks provenance (the fix for missing provenance is to extend the walker, not delete content).</li><li><strong>State</strong> STANDING. Writes <code>docs/provenance/prune-orphan-images-report.md</code>.</li></ul><hr><h2 id="hero-selection" tabindex="-1">Hero selection <a class="header-anchor" href="#hero-selection" aria-label="Permalink to &quot;Hero selection&quot;">​</a></h2><h3 id="generate-hero-overrides-ts-—-hero-override-json-standing" tabindex="-1"><code>generate-hero-overrides.ts</code> — hero override JSON <strong>(STANDING)</strong> <a class="header-anchor" href="#generate-hero-overrides-ts-—-hero-override-json-standing" aria-label="Permalink to &quot;`generate-hero-overrides.ts` — hero override JSON **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npx tsx scripts/generate-hero-overrides.ts</code></li><li><strong>What</strong> Reads the <code>## ⇄ Swap proposals</code> tables in <code>docs/provenance/*-hero-audit.md</code> (from <code>audit-heroes.ts</code>) → writes <code>static/data/&lt;surface&gt;-hero-overrides.json</code>, consumed by <code>pickHero()</code> + <code>loadHeroOverrides</code>. Idempotent.</li><li><strong>When</strong> After a hero audit produces new swap proposals.</li><li><strong>Gotchas</strong> Hero per surface lives in the override JSON, NOT slot 01 — disk-copying to slot 01 is invisible if an override exists.</li><li><strong>State</strong> STANDING.</li></ul><h3 id="fix-fleet-heroes-ts-—-fleet-hero-curation-one-shot-but-kept" tabindex="-1"><code>fix-fleet-heroes.ts</code> — fleet hero curation <strong>(ONE-SHOT-BUT-KEPT)</strong> <a class="header-anchor" href="#fix-fleet-heroes-ts-—-fleet-hero-curation-one-shot-but-kept" aria-label="Permalink to &quot;`fix-fleet-heroes.ts` — fleet hero curation **(ONE-SHOT-BUT-KEPT)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>tsx scripts/fix-fleet-heroes.ts</code></li><li><strong>What</strong> Replaces bad/empty fleet <code>01.jpg</code> with curated canonical Commons filenames (resolved via Wikipedia <code>pageimages</code>, ADR-046 rationale). Old 01 shifts to a free slot; sidecar updated.</li><li><strong>When</strong> Recipe for fixing a specific fleet hero; not routine.</li><li><strong>Gotchas</strong> Commons SEARCH is noisy (&quot;Cygnus&quot; → swans) — that&#39;s why this uses curated infobox-derived filenames.</li><li><strong>State</strong> <code>HERO_OVERRIDES</code> map frozen.</li></ul><hr><h2 id="anatomy-art-separate-pipeline" tabindex="-1">Anatomy art (SEPARATE pipeline) <a class="header-anchor" href="#anatomy-art-separate-pipeline" aria-label="Permalink to &quot;Anatomy art (SEPARATE pipeline)&quot;">​</a></h2><h3 id="build-anatomy-webp-mjs-—-anatomy-art-manifest-standing" tabindex="-1"><code>build-anatomy-webp.mjs</code> — anatomy art manifest <strong>(STANDING)</strong> <a class="header-anchor" href="#build-anatomy-webp-mjs-—-anatomy-art-manifest-standing" aria-label="Permalink to &quot;`build-anatomy-webp.mjs` — anatomy art manifest **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>node scripts/build-anatomy-webp.mjs</code></li><li><strong>What</strong> Derives web-sized <code>.webp</code> (≈10× smaller, 1100 px longest edge) from the full-res <code>.png</code> anatomy originals in <code>original-assets/anatomy/</code> → <code>static/images/anatomy/</code>. Surfaced on the fleet DETAIL tab + <code>/colophon</code> (#367). Auto-derives <code>src/lib/anatomy-ids.json</code>.</li><li><strong>When</strong> After generating new anatomy art.</li><li><strong>Gotchas</strong> This is NOT the photo pipeline — it&#39;s AI-generated watercolor/pencil cutaways. To generate more without style drift, follow <a href="./../../anatomy-art-runbook"><code>docs/anatomy-art-runbook.md</code></a> (verbatim prompts, fixed model/aspect, reference-image anti-drift). Do NOT hand-edit <code>anatomy-ids.json</code> — it&#39;s regenerated here.</li><li><strong>State</strong> STANDING.</li></ul><hr><h2 id="surface-hotspots-sub-pipeline-scripts-hotspots" tabindex="-1">Surface hotspots sub-pipeline (<code>scripts/hotspots/</code>) <a class="header-anchor" href="#surface-hotspots-sub-pipeline-scripts-hotspots" aria-label="Permalink to &quot;Surface hotspots sub-pipeline (`scripts/hotspots/`)&quot;">​</a></h2><p>Orbital-surface imagery for <code>/moon</code> + <code>/mars</code> deep zoom is its OWN sub-pipeline (27 files, #309/#360/#361) — HiRISE/CTX/LROC/Kaguya crops for landing zones and along rover traverses. <strong>Runs under Node 20</strong> (<code>~/.nvm/.../v20.20.2/bin/node</code>) with the gdal-async binding (<code>node-v115</code>); the TS tier-2 fetchers run via <code>tsx</code>.</p><p>Canonical prose is in <a href="./../../../AGENTS#image-pipeline--gotchas">AGENTS.md §&quot;Image pipeline — gotchas&quot;</a> (the &quot;Orbital surface imagery&quot;, &quot;Moon REGIONAL/DETAIL/TRAVERSES&quot;, and &quot;re-fetching a hotspot base&quot; paragraphs) + <a href="./../../rfc/RFC-017">RFC-017</a>. Key entrypoints only:</p><h3 id="fetch-hotspot-imagery-ts-—-hotspot-orchestrator-standing" tabindex="-1"><code>fetch-hotspot-imagery.ts</code> — hotspot orchestrator <strong>(STANDING)</strong> <a class="header-anchor" href="#fetch-hotspot-imagery-ts-—-hotspot-orchestrator-standing" aria-label="Permalink to &quot;`fetch-hotspot-imagery.ts` — hotspot orchestrator **(STANDING)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>npm run images:hotspots</code></li><li><strong>What</strong> Drives the Mars (HiRISE/CTX/panorama) + Moon (Kaguya regional / LROC featured / panorama / traverse) tier-2/tier-3 fetchers; each self-credits provenance via <code>hotspots/provenance.ts</code>.</li><li><strong>When</strong> Adding/refreshing a surface site&#39;s deep-zoom imagery.</li><li><strong>Gotchas</strong> <strong>Re-fetching a base = regenerate its variants</strong> (below) — the fetchers write only the 2048² base, not the <code>.1x1</code> the surface scene consumes. Half-baked re-fetch → empty tile at deepest zoom; <code>validate-data</code> gate #8 catches it.</li><li><strong>State</strong> STANDING.</li></ul><p><strong>Other standing hotspot tools</strong> (per-body fetchers, called by the orchestrator or directly): <code>fetch-mars.ts</code> / <code>fetch-mars-ctx.ts</code> / <code>fetch-mars-panoramas.ts</code> / <code>fetch-mars-traverse.ts</code>; <code>fetch-moon.ts</code> / <code>fetch-moon-regional.ts</code> / <code>fetch-moon-kaguya-regional.ts</code> / <code>fetch-moon-featured-images.ts</code> / <code>fetch-moon-panoramas.ts</code> / <code>fetch-moon-traverse.ts</code>; catalog/crop libs <code>hirise-catalog.ts</code>, <code>lroc-fetch.ts</code>, <code>lroc-products.ts</code>, <code>ctx-mosaic.ts</code>, <code>gdal-crop.ts</code>, <code>panorama-padder.ts</code>; provenance <code>provenance.ts</code>; co-registration helpers <code>coreg-*.mjs</code> / <code>verify-coreg-geometry.mjs</code> / <code>validate-coreg.mjs</code>.</p><h3 id="regenerate-tier3-variants-mjs-—-variant-regen-standing-mandatory-after-base-change" tabindex="-1"><code>regenerate-tier3-variants.mjs</code> — variant regen <strong>(STANDING, mandatory after base change)</strong> <a class="header-anchor" href="#regenerate-tier3-variants-mjs-—-variant-regen-standing-mandatory-after-base-change" aria-label="Permalink to &quot;`regenerate-tier3-variants.mjs` — variant regen **(STANDING, mandatory after base change)**&quot;">​</a></h3><ul><li><strong>Command</strong> <code>node scripts/hotspots/regenerate-tier3-variants.mjs static/images/hotspots/&lt;body&gt;/&lt;site&gt;/tier2-*.jpg [...]</code></li><li><strong>What</strong> Re-runs <code>generateVariants()</code> (centred focal point) for a base without a vision-API pass. Despite the <code>tier3</code> name, regenerates the <code>.1x1</code> variant (the only ratio since 2026-06-26).</li><li><strong>When</strong> <strong>After ANY hotspot base re-fetch/re-point.</strong> Gated by <code>validate-data</code> #8.</li><li><strong>Gotchas</strong> No vision cost, no manifest rewrite — manifest already references the path. Don&#39;t <code>--no-verify</code> past the gate; run the command it prints.</li><li><strong>State</strong> STANDING.</li></ul><p><strong>One-shot hotspot backfills (KEPT):</strong> <code>backfill-imagery-provenance.ts</code> (mints route-patch provenance + patches spacecraft fields onto existing Mars entries), <code>reupsert-tier2-provenance.ts</code> (re-adds tier-2 regional provenance the provenance rebuild drops because hotspots aren&#39;t in its curated maps), <code>build-moon-traverses.mjs</code> (writes V1 procedural Moon traverse polylines), <code>author-moon-ground.mjs</code> / <code>backfill-tier2-ground.mjs</code> (author co-scale ground extents). Re-run only if their inputs change.</p><hr><h2 id="shared-infra-scripts-lib" tabindex="-1">Shared infra (<code>scripts/lib/</code>) <a class="header-anchor" href="#shared-infra-scripts-lib" aria-label="Permalink to &quot;Shared infra (`scripts/lib/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Role</th></tr></thead><tbody><tr><td><code>staging.ts</code></td><td>RFC-029 staging redirect — <code>toStagingDest()</code>, <code>STAGED_CATEGORIES</code>. Gallery slots stage; textures/logos/covers pass through.</td></tr><tr><td><code>phash.ts</code></td><td>DCT pHash + <code>hammingDistance</code> (≤4 identical, 5–10 same-subject, &gt;20 unrelated).</td></tr><tr><td><code>image-bytes.ts</code></td><td><code>coerceToJpeg()</code> / <code>isJpegBytes()</code> — the GH #251 mime contract. Every <code>.jpg</code> write round-trips through it.</td></tr><tr><td><code>agency-resolver.mjs</code></td><td>Multi-primary tier chain (agency primaries → institutional secondary → Commons) over <code>agency-archives.json</code> schema v2.</td></tr><tr><td><code>vision-judge.mjs</code></td><td>Haiku 4.5 content-vs-subject QA (~$0.0004/img); fail-open <code>unsure</code> on errors.</td></tr><tr><td><code>relevance-gate.mjs</code></td><td>0..1 relevance scorer used by <code>agency-resolver.mjs</code> across every tier to filter keyword-matched-but-tangential records.</td></tr></tbody></table><hr><h2 id="variant-policy-load-bearing" tabindex="-1">Variant policy (load-bearing) <a class="header-anchor" href="#variant-policy-load-bearing" aria-label="Permalink to &quot;Variant policy (load-bearing)&quot;">​</a></h2><p><code>1x1</code> is the <strong>only</strong> generated crop ratio (since 2026-06-26). <code>4x3</code>/<code>16x9</code> were retired as dead code — no UI consumed them (<code>pickVariant</code> callers all pass <code>&#39;thumbnail&#39;</code>; <code>pickVariant</code> returns <code>undefined</code> for other surfaces → caller uses the raw source path). The single lever is <code>VARIANT_RATIOS</code> in <code>scripts/vision/crop-variants.ts</code> (<code>[&#39;1x1&#39;]</code>), which feeds <code>build-manifest.ts</code>, <code>score-images.ts</code>, and <code>regenerate-tier3-variants.mjs</code>. To re-introduce a ratio, add it back <strong>and wire a real consumer first</strong>. Note: <code>static/textures/*.{4x3,16x9}.jpg</code> are a SEPARATE pipeline (planet-texture cards on <code>/credits</code>) — untouched.</p><hr><p><em>Orrery · <code>docs/reference/tooling/image-pipeline.md</code> · index entry — deep ref is <a href="./../../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a>.</em></p>',82)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
